const BASE_REWARD_CSS = '\n.reward-window{position:absolute;inset:0}\n.reward-window{--reward-zone-top:64px;--reward-zone-bottom:56px}\n.reward-window .dialog>*{flex-shrink:0}\n/* The reward window keeps its own fitted height (whole item lines, artboard D_Reward) instead of\n   the fixed info height (client-sdk PR 895): its content is known when it opens, so the box does not move;\n   «Отлично» stays in flow after the card, the body scrolls as a whole. */\n.reward-window .dialog{height:auto}\n.reward-window .dialog :is(.window-actions,.std-actions,.dr-actions,.window-footer){position:static}\n.reward-window>.dialog-backdrop{z-index:auto}\n.reward-burst{position:relative;display:grid;place-items:center;height:144px;flex:none}\n.reward-burst>span{grid-area:1/1}\n/* Info popup height is fixed at 50% (owner 16.10): a lower burst on phone heights keeps a line of the list. */\n@media(orientation:portrait) and (max-height:900px){.reward-burst{height:104px}\n .reward-burst .mp-sparkle--2{top:64px}.reward-burst .mp-sparkle--4{top:80px}}\n.reward-flash{width:128px;height:128px;border-radius:50%;opacity:0;pointer-events:none;\n background:radial-gradient(circle,color-mix(in srgb,var(--mp-gold) 75%,transparent),\n color-mix(in srgb,var(--mp-gold) 30%,transparent) 45%,transparent 70%);animation:reward-flash .7s ease-out}\n.reward-spark{width:8px;height:8px;border-radius:50%;background:var(--mp-gold);opacity:0;\n pointer-events:none;box-shadow:0 0 8px var(--mp-gold);animation:reward-spark .8s ease-out .08s}\n.reward-spark[data-i="0"]{--a:22deg}.reward-spark[data-i="1"]{--a:67deg}.reward-spark[data-i="2"]{--a:112deg}.reward-spark[data-i="3"]{--a:157deg}.reward-spark[data-i="4"]{--a:202deg}.reward-spark[data-i="5"]{--a:247deg}.reward-spark[data-i="6"]{--a:292deg}.reward-spark[data-i="7"]{--a:337deg}\n.reward-hero{display:grid;place-items:center;animation:reward-pop .5s cubic-bezier(.3,1.6,.6,1)}\n.reward-hero svg,.reward-hero img{display:block;object-fit:contain}\n\n.reward-hero [data-part=icon],.reward-hero img{display:block;object-fit:contain}\n.reward-hero-icons{display:flex;align-items:center;justify-content:center;gap:8px}\n.reward-hero-icon{display:grid;place-items:center;filter:drop-shadow(0 4px 10px color-mix(in srgb,var(--mp-gold) 45%,transparent))}\n.reward-chest .ch-gold{fill:var(--mp-gold);stroke:var(--mp-gold-edge);stroke-width:2}\n.reward-chest .ch-lid{fill:var(--mp-wood-dark);stroke:var(--mp-wood-edge);stroke-width:2;stroke-linejoin:round}\n.reward-chest .ch-wood{fill:var(--mp-wood)}.reward-chest .ch-rim{fill:var(--mp-wood-dark)}\n.reward-chest .ch-box{fill:var(--mp-wood);stroke:var(--mp-wood-edge);stroke-width:2}\n.reward-chest .ch-gem{fill:var(--mp-violet);stroke:var(--mp-line-strong);stroke-width:2;stroke-linejoin:round}\n.reward-chest .ch-hole{fill:var(--mp-wood-edge)}\n.reward-burst .mp-sparkle{position:absolute}.reward-burst .mp-sparkle--gold path{fill:var(--mp-gold)}\n.reward-burst .mp-sparkle--violet path{fill:var(--mp-violet-text)}\n.reward-burst .mp-sparkle--white path{fill:var(--mp-text)}\n.reward-burst .mp-sparkle--1{left:calc(50% - 73px);top:14px}.reward-burst .mp-sparkle--2{left:calc(50% - 89px);top:84px}\n.reward-burst .mp-sparkle--3{left:calc(50% + 57px);top:30px}.reward-burst .mp-sparkle--4{left:calc(50% + 55px);top:104px}\n.reward-burst .mp-sparkle--5{left:calc(50% - 39px);top:0}\n.reward-box{position:relative;display:flex;flex-direction:column;min-height:0;padding:4px 16px;\n border:1px solid var(--mp-line);border-radius:12px;background:var(--mp-surface)}\n.reward-window .dialog>.reward-box{flex-shrink:1}\n.reward-sub{flex:none;margin:8px 0 4px;font:600 13px/1.4 var(--mp-font-ui);color:var(--mp-text-3)}\n.reward-items{position:relative;min-height:0;margin:0;padding:0;list-style:none;overflow:auto;\n overscroll-behavior:contain;scroll-snap-type:y mandatory}\n.reward-line{display:flex;align-items:center;gap:12px;min-height:56px;padding:6px 0;box-sizing:border-box;\n scroll-snap-align:start;\n border-bottom:1px solid var(--mp-line);animation:reward-line .35s ease-out both}\n.reward-line:last-child{border-bottom:0}\n.reward-line:nth-child(2){animation-delay:60ms}.reward-line:nth-child(3){animation-delay:120ms}.reward-line:nth-child(4){animation-delay:180ms}.reward-line:nth-child(5){animation-delay:240ms}.reward-line:nth-child(6){animation-delay:300ms}.reward-line:nth-child(7){animation-delay:360ms}\n.reward-art{flex:none;display:grid;place-items:center;min-width:32px;height:32px}\n.reward-art img{width:32px;height:32px;object-fit:contain}.reward-glyph{font-size:24px;color:var(--mp-gold)}\n.reward-art .mp-glyph{display:inline-grid;place-items:center;min-width:32px;height:32px;box-sizing:border-box;\n padding:0 4px;border-radius:8px;border:1px solid var(--mp-line-strong);background:var(--mp-raised);\n color:var(--mp-violet-text);font:700 14px/1 var(--mp-font-ui)}\n.reward-art .mp-glyph--bolt{color:var(--mp-gold)}\n.reward-name{flex:1;min-width:0;color:var(--mp-text-2);overflow-wrap:anywhere}\n.reward-amount{flex:none;white-space:nowrap;font:700 17px/1.2 var(--mp-font-ui);color:var(--mp-text)}\n.reward-line[data-gold] .reward-amount{color:var(--mp-gold)}\n.reward-fly,.reward-spot{position:fixed;inset:0;pointer-events:none;overflow:hidden}\n.reward-lit{position:absolute;display:flex;align-items:center;filter:drop-shadow(0 0 4px var(--mp-gold)) drop-shadow(0 0 10px color-mix(in srgb,var(--mp-gold) 60%,transparent))}\n.reward-lit .hud{flex-wrap:nowrap}\n.reward-lit .hud>.hud-capsule,.reward-lit .hud>.hud-item[data-capsule]{border-color:var(--mp-gold)}\n.reward-lit .hud-value{color:var(--mp-gold)}\n.reward-coin{position:absolute;left:0;top:0;width:32px;height:32px;object-fit:contain;will-change:transform}\n@keyframes reward-flash{0%{opacity:0;transform:scale(.3)}30%{opacity:1}100%{opacity:0;transform:scale(1.6)}}\n@keyframes reward-spark{0%{opacity:1;transform:rotate(var(--a)) translateX(12px)}\n 100%{opacity:0;transform:rotate(var(--a)) translateX(84px) scale(.4)}}\n@keyframes reward-pop{from{transform:scale(.2);opacity:0}to{transform:scale(1);opacity:1}}\n@keyframes reward-line{from{transform:translateY(8px);opacity:0}to{transform:none;opacity:1}}\n@keyframes reward-twinkle{from{opacity:.5;transform:scale(.85)}to{opacity:1;transform:scale(1)}}\n@media(prefers-reduced-motion:no-preference){.reward-burst .mp-sparkle{\n animation:reward-twinkle 1.6s ease-in-out infinite alternate}\n .reward-burst .mp-sparkle--2,.reward-burst .mp-sparkle--4{animation-delay:-.8s}}\n@media(orientation:landscape) and (max-height:520px){:host([data-pop-kind]) .reward-window>.dialog-backdrop{justify-items:end;\n  padding:var(--reward-zone-top) var(--mp-gap) var(--reward-zone-bottom)}\n .reward-window .dialog{display:grid;\n width:min(600px,100%);height:100%;padding:16px 24px;gap:12px 16px;grid-template-columns:216px minmax(0,1fr);\n grid-template-rows:auto minmax(0,1fr) auto;grid-template-areas:"head head" "art box" "art act"}\n .reward-window .dialog-head{grid-area:head}\n .reward-burst{grid-area:art;height:auto;min-height:0;border:1px solid var(--mp-line);\n  border-radius:12px;background:var(--mp-surface)}\n .reward-burst .mp-sparkle--1{left:calc(50% - 78px);top:calc(50% - 71px)}\n .reward-burst .mp-sparkle--2{left:calc(50% - 86px);top:calc(50% + 11px)}\n .reward-burst .mp-sparkle--3{left:calc(50% + 62px);top:calc(50% - 59px)}\n .reward-burst .mp-sparkle--4{left:calc(50% + 66px);top:calc(50% + 19px)}\n .reward-burst .mp-sparkle--5{left:calc(50% - 8px);top:calc(50% - 85px)}\n .reward-box{grid-area:box;align-self:start;max-height:100%;box-sizing:border-box}.reward-sub{margin:4px 0 0}\n .reward-line{min-height:44px;padding:4px 0}\n .reward-actions{grid-area:act}}\n@media(prefers-reduced-motion:reduce){.reward-flash,.reward-spark,.reward-hero,.reward-line{animation:none}\n .reward-flash,.reward-spark{display:none}}\n';
export const CHEST_REWARD_CSS = `
.reward-chest-info{border-radius:8px}
.reward-chest-badge{display:grid;place-items:center;width:16px;height:16px;border-radius:50%;
 background:var(--mp-raised);border:1px solid var(--mp-line-strong);color:var(--mp-text);
 font:700 12px/1 var(--mp-font-ui);pointer-events:none}
.reward-random-mark{color:var(--mp-text);text-shadow:0 1px 2px var(--mp-night)}
.reward-chest-result{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:flex-end}
.reward-chest-result>.reward-items{flex-basis:100%}
@media(prefers-reduced-motion:no-preference){
 .reward-grid-entry[data-chest-state=closed] .mp-art-icon{
  filter:drop-shadow(0 0 4px var(--mp-gold));animation:reward-twinkle 1.6s ease-in-out infinite alternate}}
`;
export const REWARD_CSS = BASE_REWARD_CSS + CHEST_REWARD_CSS;
